use vstd::prelude::*;

verus! {

/// Specification-level projection: imaginary part of a complex pair.
spec fn imag_of(p: (f64, f64)) -> f64 {
    p.1
}

fn imag(val: Vec<(f64, f64)>) -> (out: Vec<f64>)
    ensures
        out@.len() == old(val@).len(),
        forall|i: int|
            0 <= i < old(val@).len()
            ==> out@[i] == imag_of(old(val@)[i]),
        forall|i: int|
            0 <= i < old(val@).len()
            && imag_of(old(val@)[i]) == 0.0
            ==> out@[i] == 0.0,
        forall|i: int|
            0 <= i < old(val@).len()
            && (old(val@)[i].0 != 0.0 || old(val@)[i].1 != 0.0)
            ==> out@[i] == imag_of(old(val@)[i])
{
    let n = val.len();
    let mut out: Vec<f64> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == old(val@).len(),
            i <= n,
            out@.len() == i as int,
            forall|j: int| 0 <= j < i as int ==> out@[j] == imag_of(old(val@)[j]),
        decreases (n - i)
    {
        // Safe indexing due to loop guard i < n
        let p = val[i];
        out.push(p.1);
        i = i + 1;
    }

    out
}

} // verus!

